#!/usr/bin/env bash
# Builds everything that is served at https://deco.hero-apps.com into web-dist/:
#   web-dist/         the landing pages (site/*, generated by scripts/build-site.mjs)
#   web-dist/app/     the web app (mobile/dist-web, from `npm run build:web` in mobile/)
#
#   ./scripts/build-web.sh                       release build (needs mobile/.env.web, see WEB_CONSOLE_TASKS.md)
#   ./scripts/build-web.sh --allow-placeholder   preview build without the real web settings
#   ./scripts/build-web.sh --site-only           landing pages only, skips the web app
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="$ROOT/web-dist"
SITE_ONLY=0
APP_ARGS=()
for arg in "$@"; do
  case "$arg" in
    --site-only) SITE_ONLY=1 ;;
    *) APP_ARGS+=("$arg") ;;
  esac
done

echo "== Landing pages"
node "$ROOT/scripts/build-site.mjs"

if [ "$SITE_ONLY" -eq 0 ]; then
  echo "== Web app"
  if [ ! -d "$ROOT/mobile/node_modules" ]; then
    echo "mobile/node_modules is missing. Run: cd mobile && npm install" >&2
    exit 1
  fi
  if [ "${#APP_ARGS[@]}" -gt 0 ]; then
    (cd "$ROOT/mobile" && npm run build:web -- "${APP_ARGS[@]}")
  else
    (cd "$ROOT/mobile" && npm run build:web)
  fi
  if [ ! -f "$ROOT/mobile/dist-web/index.html" ]; then
    echo "mobile/dist-web/index.html was not built." >&2
    exit 1
  fi
fi

echo "== Assemble web-dist/"
rm -rf "$OUT"
mkdir -p "$OUT"
# site/ holds only public files, plus vercel.json and .vercelignore.
cp -R "$ROOT/site/." "$OUT/"

if [ "$SITE_ONLY" -eq 0 ]; then
  mkdir -p "$OUT/app"
  cp -R "$ROOT/mobile/dist-web/." "$OUT/app/"

  # The app is served under /app, so its files must be referenced as /app/..., not /_expo/...
  if grep -Eq '(src|href)="/(_expo|assets)/' "$OUT/app/index.html"; then
    echo "web-dist/app/index.html loads files from the site root (/_expo or /assets)." >&2
    echo "The Expo web build needs its base URL set to /app (experiments.baseUrl in mobile/app.json)." >&2
    exit 1
  fi

  # Expo puts the Instrument Serif files under assets/node_modules/..., and the Vercel CLI never uploads
  # a folder called node_modules, so the font would 404. Move it to assets/vendor and fix the references.
  if [ -d "$OUT/app/assets/node_modules" ]; then
    mv "$OUT/app/assets/node_modules" "$OUT/app/assets/vendor"
    while IFS= read -r file; do
      LC_ALL=C sed -i.bak 's#assets/node_modules#assets/vendor#g' "$file"
      rm -f "$file.bak"
    done < <(grep -rlI --include='*.js' --include='*.html' --include='*.css' --include='*.json' 'assets/node_modules' "$OUT/app" || true)
  fi
  if grep -rqI 'assets/node_modules' "$OUT/app"; then
    echo "web-dist/app still refers to assets/node_modules:" >&2
    grep -rlI 'assets/node_modules' "$OUT/app" >&2
    exit 1
  fi
  if find "$OUT" -type d -name node_modules | grep -q .; then
    echo "web-dist/ contains a node_modules folder, which Vercel will not upload:" >&2
    find "$OUT" -type d -name node_modules >&2
    exit 1
  fi
fi

# Belt and braces: the deploy folder must not contain anything secret or any source file.
LEAKS="$(find "$OUT" \( -name '.env*' -o -name '*.jks' -o -name '*.keystore' -o -name '*.pem' -o -name '*.sh' \
  -o -name '*.py' -o -name '*.ts' -o -name '*.tsx' -o -name '*key*.json' -o -name 'google-services.json' \) -print)"
if [ -n "$LEAKS" ]; then
  echo "These files must not be deployed. Remove them from site/ or mobile/dist-web/:" >&2
  echo "$LEAKS" >&2
  exit 1
fi

echo "== Done: $OUT"
du -sh "$OUT" | cut -f1
